style.css:
@-moz-document domain("chessable.com") {
.board-brown {
    background-image: url(https://images.chesscomfiles.com/chess-themes/boards/red/200.png) !important;
  }

  .board-red {
    background-image: url(https://images.chesscomfiles.com/chess-themes/boards/red/200.png) !important;
  }

  .board-blue {
    background-image: url(https://images.chesscomfiles.com/chess-themes/boards/red/200.png) !important;
  }

  .board-green {
    background-image: url(https://images.chesscomfiles.com/chess-themes/boards/red/200.png) !important;
  }

  .piece-417db {
    background-size: contain;
  }

  .piece-417db svg {
    display: none;
  }

  /* Black Pieces */

  .piece-417db[data-piece='bP'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/bp.png);
  }

  .piece-417db[data-piece='bN'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/bn.png);
  }

  .piece-417db[data-piece='bB'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/bb.png);
  }

  .piece-417db[data-piece='bR'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/br.png);
  }

  .piece-417db[data-piece='bQ'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/bq.png);
  }

  .piece-417db[data-piece='bK'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/bk.png);
  }

  /* White Pieces */

  .piece-417db[data-piece='wP'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/wp.png);
  }

  .piece-417db[data-piece='wN'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/wn.png);
  }

  .piece-417db[data-piece='wB'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/wb.png);
  }

  .piece-417db[data-piece='wR'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/wr.png);
  }

  .piece-417db[data-piece='wQ'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/wq.png);
  }

  .piece-417db[data-piece='wK'] {
    background-image: url(https://images.chesscomfiles.com/chess-themes/pieces/bases/300/wk.png);
  }
}
